CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--b);color:var(--i);font:16px/1.55 Arial,sans-serif;overflow-x:hidden}a{color:inherit}.w{width:min(1160px,calc(100% - 36px));margin:auto}header{position:fixed;top:0;left:0;right:0;z-index:9;background:color-mix(in srgb,var(--b) 88%,transparent);backdrop-filter:blur(14px);border-bottom:1px solid color-mix(in srgb,var(--i) 14%,transparent)}nav{height:74px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{font-weight:800;letter-spacing:-.04em;text-decoration:none;max-width:55%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.links{display:flex;gap:22px;align-items:center}.links a{text-decoration:none}.btn{display:inline-flex;padding:12px 18px;border-radius:999px;background:var(--a);color:white;text-decoration:none;font-weight:800}.menu{display:none;border:1px solid currentColor;background:none;color:inherit;border-radius:50%;width:44px;height:44px}main{padding-top:74px}.hero{min-height:calc(100svh - 74px);padding:70px max(18px,calc((100vw - 1160px)/2));display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:48px}.hero.center{grid-template-columns:1fr;text-align:center}.hero.center .copy{max-width:900px;margin:auto}.hero.asym{grid-template-columns:.75fr 1.25fr}.hero.editorial h1{font-family:Georgia,serif;font-weight:400}.hero.full{grid-template-columns:1fr;background:linear-gradient(135deg,var(--b),color-mix(in srgb,var(--a) 17%,var(--b)))}.hero.full .art{position:absolute;right:4%;width:43%;opacity:.55}.copy{position:relative;z-index:2}.k{font-size:.75rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--a)}h1,h2,h3{margin:0;line-height:.96;letter-spacing:-.045em}h1{font-size:clamp(3.1rem,7vw,7rem);margin:18px 0 26px}.copy p{font-size:clamp(1rem,1.6vw,1.25rem);max-width:680px;opacity:.75}.acts{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}.ghost{padding:12px 18px;border:1px solid color-mix(in srgb,var(--i) 30%,transparent);border-radius:999px;text-decoration:none}.art{min-height:450px;border-radius:28px;background:linear-gradient(145deg,var(--a),color-mix(in srgb,var(--i) 92%,black));position:relative;overflow:hidden}.art:before,.art:after{content:"";position:absolute;border:2px solid rgba(255,255,255,.48);border-radius:50%;width:70%;aspect-ratio:1;left:-15%;top:10%}.art:after{left:40%;top:45%;width:60%}.tag{position:absolute;left:18px;bottom:18px;padding:9px 13px;background:color-mix(in srgb,var(--b) 84%,transparent);border-radius:999px;z-index:2;font-size:.72rem}.demo{display:block;margin-top:18px;font-size:.68rem;opacity:.55}section{padding:90px 0}.head{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:end;margin-bottom:36px}.head h2{font-size:clamp(2.7rem,5vw,5.2rem)}.head p{opacity:.65}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{padding:26px;border:1px solid color-mix(in srgb,var(--i) 13%,transparent);border-radius:24px;background:color-mix(in srgb,var(--b) 88%,var(--i));min-height:175px;transition:.3s}.card:hover{transform:translateY(-5px)}.card small{color:var(--a);font-weight:800}.card h3{font-size:1.65rem;margin-top:24px}.card p{opacity:.6}.story{background:color-mix(in srgb,var(--b) 94%,var(--i))}.storybox{display:grid;grid-template-columns:.8fr 1.2fr;gap:55px}.sig{min-height:430px;border-radius:28px;background:linear-gradient(160deg,var(--a),color-mix(in srgb,var(--b) 55%,var(--i)));display:flex;align-items:end;padding:28px;font-size:clamp(4rem,9vw,8rem);font-weight:900}.quote{font:clamp(1.4rem,2.5vw,2.4rem)/1.2 Georgia,serif;border-left:3px solid var(--a);padding:24px;margin:24px 0}.facts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.fact{padding:18px;border-top:1px solid color-mix(in srgb,var(--i) 20%,transparent);overflow-wrap:anywhere}.fact small{display:block;opacity:.5}.contact{background:var(--i);color:var(--b)}.contacts{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:color-mix(in srgb,var(--b) 20%,transparent)}.contacts a{padding:24px;background:var(--i);text-decoration:none;min-height:110px}.contacts small{display:block;opacity:.55}.ticker{white-space:nowrap;overflow:hidden;border-block:1px solid color-mix(in srgb,var(--i) 15%,transparent);padding:13px;font-weight:800;text-transform:uppercase}.ticker span{display:inline-block;animation:move 16s linear infinite}@keyframes move{to{transform:translateX(-50%)}}footer{padding:24px 0;font-size:.78rem;opacity:.65}.acc p{max-height:0;opacity:0;overflow:hidden}.acc.on p{max-height:80px;opacity:.7}.spot:hover{box-shadow:0 0 0 2px var(--a) inset}.sticky .sig{position:sticky;top:100px}.reveal{animation:up .7s ease both}@keyframes up{from{opacity:0;transform:translateY(18px)}}@media(max-width:820px){nav{height:66px}.links{display:none;position:fixed;top:66px;left:0;right:0;background:var(--b);padding:20px;flex-direction:column;align-items:stretch;border-bottom:1px solid color-mix(in srgb,var(--i) 15%,transparent)}.links.open{display:flex}.menu{display:block}.hero,.hero.center,.hero.asym,.hero.full{display:flex;flex-direction:column;min-height:auto;padding-top:50px;text-align:left}.hero.full .art{position:relative;right:auto;width:100%;opacity:1}h1{font-size:clamp(3rem,14vw,5rem)}.art{width:100%;min-height:340px}.head,.storybox{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.contacts{grid-template-columns:1fr}.facts{grid-template-columns:1fr 1fr}.sticky .sig{position:relative;top:auto}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}}'''
