def page(x,idx):
 n,name,slug,place,prof,phone,email,fb,ig,book,web,svcs,note,arch,hero,motion=x;b,i,a=P[idx];S=svcs.split('|'); cards=''.join(f'<article class="card {"acc" if motion=="accordion" else "spot" if motion=="spotlight" else ""}"><small>{j+1:02d}</small><h3>{E(s)}</h3><p>{E(place.split(",")[0])}</p></article>' for j,s in enumerate(S));cta=book or tel(phone);ct='Időpontfoglalás' if book else 'Hívás / egyeztetés';soc=' '.join(([f'<a href="{E(fb)}">Facebook ↗</a>'] if fb else [])+([f'<a href="{E(ig)}">Instagram ↗</a>'] if ig else [])) or '—';contacts=f'<a href="{tel(phone)}"><small>Telefon</small><strong>{E(phone)}</strong></a>'+ (f'<a href="mailto:{E(email)}"><small>E-mail</small><strong>{E(email)}</strong></a>' if email else '')+f'<a href="https://www.google.com/maps/search/?api=1&query={E(place.replace(" ","+"))}"><small>Helyszín</small><strong>{E(place)}</strong></a>';ticker=f'<div class="ticker"><span>{E(" • ".join(S*4))}</span></div>' if motion=='marquee' else '';initial=''.join(p[0] for p in name.split()[:2]).upper();extra=' sticky' if motion=='sticky' else '';return f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(name)} — demo</title><meta name="description" content="{E(name)} bemutató weboldal koncepció"><style>:root{{--b:{b};--i:{i};--a:{a}}}{CSS}</style></head><body><header><nav class="w"><a class="logo" href="#top">{E(name)}</a><div class="links" id="nav"><a href="#szolg">Szolgáltatások</a><a href="#rolunk">Röviden</a><a href="#kapcsolat">Kapcsolat</a><a class="btn" href="{E(cta)}">{ct}</a></div><button class="menu" id="menu" aria-label="Menü" aria-expanded="false">☰</button></nav></header><main id="top"><section class="hero {hero}"><div class="copy"><div class="k">{E(prof)} • {E(place.split(',')[0])}</div><h1>{E(name)}</h1><p>{E(note)}</p><div class="acts"><a class="btn" href="{E(cta)}">{ct}</a><a class="ghost" href="#szolg">Felfedezem</a></div><span class="demo">Demo koncepció • a vizuális elemek csak irányt mutatnak.</span></div><div class="art"><span class="tag">{E(arch)}</span></div></section>{ticker}<section id="szolg"><div class="w"><div class="head"><h2>Szolgáltatások</h2><p>Átlátható, mobilon is könnyen bejárható bemutatás.</p></div><div class="grid {motion}">{cards}</div></div></section><section class="story{extra}" id="rolunk"><div class="w storybox"><div class="sig">{E(initial)}</div><div><div class="k">Helyi jelenlét</div><h2 style="font-size:clamp(2.8rem,5vw,5.5rem);margin-top:16px">{E(place.split(',')[0])}</h2><blockquote class="quote">{E(note)}</blockquote><div class="facts"><div class="fact"><small>Cím</small>{E(place)}</div><div class="fact"><small>Telefon</small>{E(phone)}</div><div class="fact"><small>Web</small><a href="{E(web)}">Jelenlegi online felület ↗</a></div><div class="fact"><small>Közösségi média</small>{soc}</div></div></div></div></section><section class="contact" id="kapcsolat"><div class="w"><div class="head"><h2>Kapcsolat</h2><p>A részletekről a vállalkozás saját elérhetőségein lehet egyeztetni.</p></div><div class="contacts">{contacts}</div></div></section></main><footer><div class="w">{E(name)} • SCH Agency demo koncepció • nem hivatalos ügyféloldal</div></footer><script>const m=document.querySelector('#menu'),v=document.querySelector('#nav');m.onclick=()=>{{let o=v.classList.toggle('open');m.setAttribute('aria-expanded',o);m.textContent=o?'×':'☰'}};v.querySelectorAll('a').forEach(a=>a.onclick=()=>v.classList.remove('open'));document.querySelectorAll('.acc').forEach(c=>c.onclick=()=>c.classList.toggle('on'));</script></body></html>'''
